    fbBtn: '✉ Write to the developers', fbTitle: 'Write to us', fbHint: 'What do you like, what broke, what is missing? We read every message.', fbContact: 'Contact (optional)', fbSend: 'Send', fbCancel: 'Cancel', fbThanks: 'Thank you! Your message was sent 💌', fbFail: 'Could not send. Please try again later.', fbCopied: 'The address is not set up yet. The text was copied, please send it to the developers.', fbEmpty: 'Write a few words first.',
    newsTitle: '📮 Mail from the developers', newsSub: 'Fresh CapyTap news',
    newsIntro: 'Hi, friend! This time the news is in a newspaper: a clock tower, a new loading screen and many small things. Turn the pages!',
    newsH0: 'A newspaper instead of a letter.', newsT0: 'The mail from the developers is now a newspaper: it unfolds and the pages turn. Swipe, tap or use the arrows.',
    newsH1: 'The clock tower.', newsT1: 'A big clock tower rose on the mall. Before the trip it strikes: once on the first night, twice on the second and three times on the third. Tap it to set off for a new era.',
    newsH2: 'New loading screen.', newsT2: 'A lively night city with windows, cars and birds, and useful tips below. Tap a tip to see the next one.',
    newsH3: 'A new witch.', newsT3: 'The witch on a broom got prettier: a big hat, a fluffy broom and a trail of stars.',
    newsH4: 'Bigger markets.', newsT4: 'On a vertical phone markets of every level are bigger and the brown strips at the edges are gone.',
    newsH5: 'Bitten clouds.', newsT5: 'In the Cotton Clouds skin some of the clouds look as if somebody took a bite.',
    newsH6: 'The rain drop.', newsT6: 'The little drop that turns the rain on now hangs on the right by the shop sign.',
    newsH7: 'Crisp frames.', newsT7: 'Menu frames have a clear outline on all sides, and tab labels no longer hide under the padlock.',
    newsH8: 'Capy at night.', newsT8: 'In the dark Capy gets a warm outline so she stands out, and the fog no longer veils the animals.',
    newsSign: 'Thanks for playing! Tell us what you want to see next. — The CapyTap team', newsClose: 'Got it!',
    fear0: 'Eek!', fear1: 'Mommy!', fear2: 'My bun!', fear3: 'I was just strolling!', fear4: 'Where are you going?!', fear5: 'Run!',
    seasonIntroTitle: 'Seasons unlocked!', seasonIntroText: 'Two eras down, and now you can pick the season yourself: spring, summer, autumn, winter or spooky Halloween. Each one changes the trees, the weather and the mood of the street. Look for the new wheel button in the menu!', seasonIntroGo: '🌸 To the seasons', seasonIntroLater: 'Later',
    mailSay0: 'Mail! Sign right here!', mailSay1: 'A letter for you! Faster than a pigeon!', mailSay2: 'Express delivery. The cap is official!', mailSay3: 'Letter delivered, paw on heart.',
    gfear0: 'A ghost!!! Mommy!', gfear1: 'Boo-- oh, it is him!', gfear2: 'I saw nothing!', gfear3: 'Someone is in the window!', gfear4: 'Run, he has no ticket!', gfear5: 'It is just a sheet, right? NO!',
    hagBang: '🧙 A witch is flying over town! Tap the "!"', hagArrived: '🏚️ The hut on chicken legs has arrived! Tap it', hagTitle: "The Witch's Hut",
    hagSub: 'Witch: "Three cauldrons, three surprises! Remember the best one, then guess!"', hagStart: 'Take a peek!', hagWatch: 'Watch closely what is where...', hagShuffle: 'Shuffling!', hagPick: 'Pick a cauldron!',
    hagGood: 'You found the main prize!', hagMiss: 'Oops, wrong one! The crystal is yours anyway.', hagDone: 'Thanks, witch!',
    clockWait: 'The clock is ticking... Build the mall and wait three nights. Then it will take you to a new era.', clockNoGain: "Too early: keep earning and the clock will pay shards for the trip.", clockWarn: 'Night three. The clock strikes three times: time to go! Tap it or open the Clock in the menu.',
    npMast: 'THE CAPY STREET NEWS', npCoverHead: 'Fresh edition!', npIn: 'In this issue:', npCap1: 'The mall clock tower at midnight.', npCap2: 'The night city on the loading screen.', npCap3: 'The new witch circles the town.',
    seasonFx_winter: 'Fluffy snow settles on the roofs', seasonFx_spring: 'Flowers and petals wake up', seasonFx_summer: 'The sun shines at full power', seasonFx_autumn: 'The wind carries golden leaves', seasonFx_halloween: 'Shh… something rustles in town',
