    speaker_pietro: 'Pietro the Rooster',
    epochTitle_0: 'Renaissance Age', epochTitle_1: 'Retro Age', epochTitle_2: 'Disco Age', epochTitle_3: 'Arcade Age',
    epochTitle_4: 'Internet Age', epochTitle_5: 'Eco Age', epochTitle_6: 'Space Age', epochTitle_7: 'Neon Future',
    epochSub_0: 'The square comes alive, pennants flutter over the street, and there is just one coin in the pocket.',
    epochSub_1: 'Pastel colours, airships and signs like in an old movie.',
    epochSub_2: 'Music, a mirror ball and colourful beams.',
    epochSub_3: 'A world of pixels, a striped sun and chiptune music.',
    epochSub_4: 'Planes in the sky, glass windows and the whole world close by.',
    epochSub_5: 'Green roofs, solar panels and windmills on the hills.',
    epochSub_6: 'Stars, rockets and a shop at the edge of the Universe.',
    epochSub_7: 'Neon signs and drones between the skyscrapers.',
